const flags = {status:'HOLD', production_recommendations:'DISABLED', source_authorized:false, independently_verified:false, eligible_for_model_scoring:false, external_calls:0};
const output = alert => [{json:{schema:'intelligence-x-watchdog-v1', alert, ...flags}}];
const items = $input.all();
const raw = items.length === 1 ? items[0]?.json?.heartbeat : null;
if (typeof raw !== 'string' || raw.length > 4096 || items[0]?.json?.error !== undefined) return output('UNAVAILABLE_OR_INVALID');
let r;
try { r = JSON.parse(raw); } catch { return output('UNAVAILABLE_OR_INVALID'); }
const keys = ['schema','generated_at','oldest_update_at','diagnostic','source_count',...Object.keys(flags)].sort();
if (!r || typeof r !== 'object' || Array.isArray(r) || Object.keys(r).sort().join(',') !== keys.join(',')) return output('UNAVAILABLE_OR_INVALID');
if (raw !== JSON.stringify(Object.fromEntries(keys.map(k=>[k,r[k]])))+'\n') return output('UNAVAILABLE_OR_INVALID');
if (r.schema !== 'intelligence-x-heartbeat-v1' || !Object.entries(flags).every(([k,v])=>r[k]===v) || !Number.isSafeInteger(r.source_count) || r.source_count<0 || r.source_count>8) return output('UNAVAILABLE_OR_INVALID');
const clock = v => {
  if (typeof v !== 'string' || !/^(?!0000)[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$/.test(v)) return NaN;
  const n = Date.parse(v);
  return Number.isFinite(n) && new Date(n).toISOString().replace('.000Z','Z')===v ? n : NaN;
};
const now = Date.now(), generated = clock(r.generated_at);
if (!Number.isFinite(generated) || generated>now || now-generated>90000) return output('HEARTBEAT_STALE_OR_FUTURE');
if (r.diagnostic === 'BLOCKED' && r.oldest_update_at === null) return output('EVIDENCE_BLOCKED');
if (r.diagnostic !== 'AGREEMENT_CANDIDATE' || r.source_count<2) return output('UNAVAILABLE_OR_INVALID');
const oldest = clock(r.oldest_update_at);
if (!Number.isFinite(oldest) || oldest>generated || now-oldest>120000) return output('SOURCE_STALE_OR_FUTURE');
return output('RESEARCH_CANDIDATE');
